    Node view(){ if(root!=null)return root; list=new VBox(10); list.setPadding(REQUEST_LIST_INSETS); title=title("Material Requests"); status=muted("Loading material requests…"); Button add=semanticButton(ControlStyles.Purpose.PRIMARY, ControlStyles.Size.STANDARD, "New Request",null); add.setOnAction(e->openNewRequestWindow()); search=new TextField();search.setPromptText("Search requests");search.getStyleClass().add("app-dialog-search-field");showDeleted=new CheckBox("Show deleted");HBox filters=new HBox(10,search,showDeleted);filters.setAlignment(Pos.CENTER_LEFT);HBox.setHgrow(search,Priority.ALWAYS);VBox section=section(title,add,status,list);section.getChildren().add(1,filters);root=new VBox(10,section); root.setPadding(new Insets(8)); root.getStyleClass().add("case-main-surface");search.textProperty().addListener((o,a,b)->render(currentData));showDeleted.selectedProperty().addListener((o,a,b)->refresh());return root; }
    private record RequestListData(List<MaterialRequestSummaryDto> requests, List<RequestStatusDto> statuses,List<RequestMethodDto> methods,List<MaterialRequestStatusHistoryDto> statusHistory) {}
    void load(){ if(!loaded) refresh(); } void refresh(){ long cid=cid(); int tid=tenant(); boolean include=showDeleted!=null&&showDeleted.isSelected(); int g=gen.incrementAndGet(); show(status,"Loading material requests…"); list.getChildren().clear(); runRead("list-material-requests",()->loadRequestListData(cid,tid,include), data->{ if(stale(g,cid)||(showDeleted!=null&&showDeleted.isSelected())!=include)return; loaded=true;currentData=data==null?new RequestListData(List.of(),List.of(),List.of(),List.of()):data;render(currentData);}, "Material requests could not be loaded."); }
    private RequestListData loadRequestListData(long cid,int tid,boolean include){List<MaterialRequestSummaryDto> requests=svc.listMaterialRequests(cid,tid,include);List<Long> ids=requests.stream().map(MaterialRequestSummaryDto::id).toList();return new RequestListData(requests,svc.listEffectiveRequestStatuses(tid),svc.listEffectiveRequestMethods(tid),svc.listStatusHistory(cid,ids,tid));}
    private void render(RequestListData data){ List<MaterialRequestSummaryDto> all=data.requests()==null?List.of():data.requests();List<RequestStatusDto> statuses=data.statuses()==null?List.of():data.statuses();List<RequestMethodDto> methods=data.methods()==null?List.of():data.methods();Map<Long,List<MaterialRequestStatusHistoryDto>> histories=(data.statusHistory()==null?List.<MaterialRequestStatusHistoryDto>of():data.statusHistory()).stream().collect(java.util.stream.Collectors.groupingBy(MaterialRequestStatusHistoryDto::materialRequestId,LinkedHashMap::new,java.util.stream.Collectors.toList()));String query=normalizeSearch(search==null?null:search.getText());var sorted=all.stream().filter(r->matchesSearch(r,query,statuses,methods)).sorted(Comparator.comparing((MaterialRequestSummaryDto r)->terminal(r.status())).thenComparing(r->Optional.ofNullable(r.nextFollowUpAt()).orElse(Optional.ofNullable(r.expectedResponseDate()).orElse(LocalDateTime.MAX))).thenComparingLong(MaterialRequestSummaryDto::id)).toList();title.setText("Material Requests ("+sorted.size()+")");list.getChildren().clear();if(sorted.isEmpty())show(status,all.isEmpty()?"No material requests yet.":"No requests match your search");else{hide(status);sorted.forEach(r->{RequestStatusPresentation presentation=resolveRequestStatusPresentation(statuses,r.status());list.getChildren().add(requestCardFactory.create(r,MaterialRequestCardFactory.Variant.LIST,presentation.name(),presentation.color(),histories.getOrDefault(r.id(),List.of()),statuses));});}}
    static String normalizeSearch(String text){return text==null?"":text.trim().toLowerCase(Locale.ROOT).replaceAll("\\s+"," ");}
    static boolean matchesSearch(MaterialRequestSummaryDto r,String query,List<RequestStatusDto> statuses,List<RequestMethodDto> methods){if(query==null||query.isBlank())return true;String status=resolveRequestStatusPresentation(statuses,r.status()).name();String method=methods.stream().filter(m->lookupValueMatches(m.systemKey(),m.name(),r.requestMethod())).map(RequestMethodDto::name).findFirst().orElse(readableStatusLabel(r.requestMethod()));return Stream.of(r.title(),r.requestedFromContactDisplayName(),r.requestedFromOrganizationName(),r.requestedFromText(),r.materialTypeName(),method,status,r.requestedByDisplayName(),r.assignedToDisplayName(),r.description()).filter(Objects::nonNull).map(CaseMaterialRequestsTabController::normalizeSearch).anyMatch(v->v.contains(query));}
    record RequestStatusPresentation(String name,String color) {}
    static RequestStatusPresentation resolveRequestStatusPresentation(List<RequestStatusDto> statuses,String savedStatus){
        RequestStatusDto resolved=statuses==null?null:statuses.stream().filter(Objects::nonNull).filter(s->lookupValueMatches(s.systemKey(),s.name(),savedStatus)).findFirst().orElse(null);
        return resolved==null?new RequestStatusPresentation(readableStatusLabel(savedStatus),null):new RequestStatusPresentation(resolved.name()==null||resolved.name().isBlank()?readableStatusLabel(savedStatus):resolved.name().trim(),resolved.color());
    }
    static String readableStatusLabel(String savedStatus){
        String value=nvl(savedStatus,"Unknown").replace('_',' ').trim().replaceAll("\\s+"," ");
        StringBuilder label=new StringBuilder(value.length());
        for(String word:value.split(" ")){if(label.length()>0)label.append(' ');label.append(word.substring(0,1).toUpperCase(Locale.ROOT)).append(word.substring(1).toLowerCase(Locale.ROOT));}
        return label.toString();
    }
    private void openNewRequestWindow(){ Stage stage=AppDialogs.createModalStage(owner.get(),"New Request"); stage.setResizable(true); VBox body=newRequestBody(stage); VBox root=AppDialogs.createSecondaryWindowShell(stage,"New Request",stage::close,body); VBox.setVgrow(body,Priority.ALWAYS); root.setPrefSize(NEW_REQUEST_WIDTH,NEW_REQUEST_HEIGHT); root.setMinSize(NEW_REQUEST_MIN_WIDTH,NEW_REQUEST_MIN_HEIGHT); AppDialogs.installSecondaryWindowResizeHandlers(stage,root); Scene scene=new Scene(root); scene.getStylesheets().add(Objects.requireNonNull(CaseMaterialRequestsTabController.class.getResource("/css/app.css")).toExternalForm()); stage.setScene(scene); stage.setMinWidth(NEW_REQUEST_MIN_WIDTH); stage.setMinHeight(NEW_REQUEST_MIN_HEIGHT); applyNewRequestStageSize(stage,root); stage.showAndWait(); }

    record RequestedFromSelection(String entityType, Long entityId, String label, ContactCardFactory.ContactCardModel contactModel, OrganizationCardFactory.OrganizationCardModel organizationModel) { boolean contact(){return contactModel!=null;} boolean organization(){return organizationModel!=null;} }

    static final class NewRequestTitleSuggester {
        private String lastAutomaticTitle = "";
        private boolean programmaticUpdate;
        private boolean manualOverride;
        String suggest(MaterialTypeDto materialType, RequestedFromSelection requestedFrom) {
            String typeName = trim(materialType == null ? null : materialType.name());
            String requestedFromName = trim(requestedFrom == null ? null : requestedFrom.label());
            boolean hasType = typeName != null && !typeName.isBlank();
            boolean hasRequestedFrom = requestedFromName != null && !requestedFromName.isBlank();
            if (hasType && hasRequestedFrom) return typeName + " requested from " + requestedFromName;
            if (hasType) return typeName + " request";
            if (hasRequestedFrom) return "Request from " + requestedFromName;
            return "";
        }
        void userEdited(String oldText, String newText) {
            if (programmaticUpdate) return;
            String current = newText == null ? "" : newText;
            if (current.isBlank()) { manualOverride = false; return; }
            manualOverride = !Objects.equals(current, lastAutomaticTitle);
        }
        void update(TextField titleField, MaterialTypeDto materialType, RequestedFromSelection requestedFrom) {
            String current = titleField.getText() == null ? "" : titleField.getText();
            if (manualOverride && !current.isBlank() && !Objects.equals(current, lastAutomaticTitle)) return;
            String next = suggest(materialType, requestedFrom);
            programmaticUpdate = true;
            try { titleField.setText(next); } finally { programmaticUpdate = false; }
            lastAutomaticTitle = next;
            manualOverride = false;
        }
        String lastAutomaticTitle(){return lastAutomaticTitle;}
        boolean manualOverride(){return manualOverride;}
    }
    VBox newRequestBody(Stage stage){ TextField titleField=new TextField(); titleField.setPromptText("New Request"); titleField.setMaxWidth(Double.MAX_VALUE); NewRequestTitleSuggester titleSuggester=new NewRequestTitleSuggester(); AtomicReference<Runnable> updateSuggestedTitleRef=new AtomicReference<>(()->{}); AtomicReference<RequestedFromSelection> requestedFrom=new AtomicReference<>(); AtomicReference<Runnable> requestedFromValidation=new AtomicReference<>(()->{}); VBox requestedFromDisplay=new VBox(6); Button requestedFromAction=semanticButton(ControlStyles.Purpose.SECONDARY, ControlStyles.Size.STANDARD, "Add",null); Button removeRequestedFrom=semanticButton(ControlStyles.Purpose.GHOST, ControlStyles.Size.SMALL, "Remove",null); removeRequestedFrom.getStyleClass().add("app-dialog-small-action"); ContactCardFactory contactCards=new ContactCardFactory(id->{}); OrganizationCardFactory organizationCards=new OrganizationCardFactory(id->{}); HBox requestedFromActions=new HBox(8,requestedFromAction,removeRequestedFrom); requestedFromActions.setAlignment(Pos.CENTER_LEFT); Runnable renderRequestedFrom=()->{requestedFromDisplay.getChildren().clear(); RequestedFromSelection v=requestedFrom.get(); requestedFromAction.setText(v==null?"Add":"Change"); removeRequestedFrom.setVisible(v!=null); removeRequestedFrom.setManaged(v!=null); if(v!=null){Node card=v.contact()?contactCards.create(v.contactModel(),ContactCardFactory.Variant.MINI):organizationCards.create(v.organizationModel(),OrganizationCardFactory.Variant.MINI); card.getStyleClass().add("requested-from-selected-card"); requestedFromDisplay.getChildren().addAll(card,requestedFromActions);}else requestedFromDisplay.getChildren().add(requestedFromActions);}; requestedFromAction.setOnAction(e->{ RequestedFromSelection selected=showRequestedFromChooser(stage); if(selected!=null){requestedFrom.set(selected); updateSuggestedTitleRef.get().run(); renderRequestedFrom.run(); requestedFromValidation.get().run(); applyNewRequestStageSize(stage,(Region)stage.getScene().getRoot());}}); removeRequestedFrom.setOnAction(e->{requestedFrom.set(null); updateSuggestedTitleRef.get().run(); renderRequestedFrom.run(); requestedFromValidation.get().run(); applyNewRequestStageSize(stage,(Region)stage.getScene().getRoot());}); VBox requestedFromBox=new VBox(6,requestedFromDisplay); renderRequestedFrom.run(); ColorCodedComboBox<MaterialTypeDto> materialType=newLookupSelector(MaterialTypeDto::name,MaterialTypeDto::color,MaterialTypeDto::description); materialType.setPromptText("Select material type"); Runnable updateSuggestedTitle=()->titleSuggester.update(titleField,materialType.getValue(),requestedFrom.get()); updateSuggestedTitleRef.set(updateSuggestedTitle); ColorCodedComboBox<RequestMethodDto> requestMethod=newLookupSelector(RequestMethodDto::name,RequestMethodDto::color,item->null); requestMethod.setPromptText("Select request method"); ColorCodedComboBox<RequestStatusDto> requestStatus=newLookupSelector(RequestStatusDto::name,RequestStatusDto::color,item->null); requestStatus.setPromptText("Select status"); UserSelectionField<CaseTaskService.AssignableUserOption> requestedBy=newUserSelectionField(stage,true); UserSelectionField<CaseTaskService.AssignableUserOption> assignedTo=newUserSelectionField(stage,true); ChoiceBox<String> followUpInterval=new ChoiceBox<>(); configureFollowUpInterval(followUpInterval); DatePicker requestDate=new DatePicker(LocalDate.now()), dueDate=new DatePicker(), requestedRangeStart=new DatePicker(), requestedRangeEnd=new DatePicker(); Label nextFollowUpDisplay=muted("No recurring follow-up scheduled"); followUpInterval.valueProperty().addListener((o,a,b)->nextFollowUpDisplay.setText(calculatedFollowUpText(intervalDays(b),null))); TextArea description=new TextArea(); description.setPromptText("Description"); description.setPrefRowCount(3); description.setMinHeight(72); description.setPrefHeight(88); description.setMaxHeight(96); description.setWrapText(true); description.setMaxWidth(Double.MAX_VALUE); styleRequestControls(titleField,materialType,requestMethod,requestStatus,followUpInterval,requestDate,dueDate,requestedRangeStart,requestedRangeEnd,description); AtomicInteger loading=new AtomicInteger(5); Label formError=muted(""); formError.getStyleClass().add("app-dialog-error"); hide(formError); AtomicBoolean saving=new AtomicBoolean(false); Button save=semanticButton(ControlStyles.Purpose.PRIMARY, ControlStyles.Size.STANDARD, "Save",null); save.setDefaultButton(true); Runnable validate=()->{String err=validateRequest(requestedFrom.get(),titleField,materialType,requestMethod,requestStatus); if(err==null)err=validateRequestedRange(requestedRangeStart.getValue(),requestedRangeEnd.getValue()); updateInvalidStates(titleField,materialType,requestMethod,requestStatus,requestedRangeStart,requestedRangeEnd); boolean disabled=!saveEligible(loading.get(),saving.get(),err); save.setDisable(disabled); save.setDefaultButton(!disabled); if(err!=null&&!saving.get()){formError.setText(err);formError.setVisible(true);formError.setManaged(true);}else hide(formError);}; requestedFromValidation.set(validate); loadNewRequestLookups(materialType,requestMethod,requestStatus,stage,loading,validate); loadNewRequestUsers(requestedBy,assignedTo,stage,loading,validate); titleField.textProperty().addListener((o,a,b)->{titleSuggester.userEdited(a,b);validate.run();}); materialType.valueProperty().addListener((o,a,b)->{updateSuggestedTitle.run();validate.run();}); requestMethod.valueProperty().addListener((o,a,b)->validate.run()); requestStatus.valueProperty().addListener((o,a,b)->validate.run()); requestedRangeStart.valueProperty().addListener((o,a,b)->validate.run()); requestedRangeEnd.valueProperty().addListener((o,a,b)->validate.run()); GridPane fields=grid(); add(fields,0,"Title:",titleField); add(fields,1,"Requested From *:",requestedFromBox); add(fields,2,"Material Type:",materialType); add(fields,3,"Request Method:",requestMethod); add(fields,4,"Status:",requestStatus); add(fields,5,"Requested By:",requestedBy); add(fields,6,"Assigned To:",assignedTo); add(fields,7,"Request Date:",requestDate); add(fields,8,"Due Date:",dueDate); add(fields,9,"Next Follow-up:",nextFollowUpDisplay); add(fields,10,"Follow-up Interval:",followUpInterval); add(fields,11,"Requested Date Start:",requestedRangeStart); add(fields,12,"Requested Date End:",requestedRangeEnd); add(fields,13,"Description:",description); GridPane.setHgrow(titleField,Priority.ALWAYS); GridPane.setHgrow(requestedFromBox,Priority.ALWAYS); GridPane.setHgrow(materialType,Priority.ALWAYS); GridPane.setHgrow(requestMethod,Priority.ALWAYS); GridPane.setHgrow(requestStatus,Priority.ALWAYS); GridPane.setHgrow(requestedBy,Priority.ALWAYS); GridPane.setHgrow(assignedTo,Priority.ALWAYS); GridPane.setHgrow(followUpInterval,Priority.ALWAYS); GridPane.setHgrow(description,Priority.ALWAYS); Button saveRef=save; save.setOnAction(e->{ if(saveRef.isDisable())return; String err=validateRequest(requestedFrom.get(),titleField,materialType,requestMethod,requestStatus); if(err!=null){formError.setText(err);show(formError,err);return;} RequestedFromSelection rf=requestedFrom.get(); var by=requestedBy.getSelectedUser(); var assignee=assignedTo.getSelectedUser(); MaterialRequestServicePort.CreateMaterialRequestCommand cmd=toCreateCommand(rf,materialType.getValue(),titleField.getText(),description.getText(),requestMethod.getValue(),requestStatus.getValue(),by,assignee,followUpInterval.getValue(),requestDate.getValue(),dueDate.getValue(),requestedRangeStart.getValue(),requestedRangeEnd.getValue()); saveNewRequest(stage,cmd,saving,validate); }); Button cancel=semanticButton(ControlStyles.Purpose.SECONDARY, ControlStyles.Size.STANDARD, "Cancel",e->{ if(confirmDiscardNewRequest(stage))stage.close(); }); HBox footer=new HBox(10,cancel,save); footer.getStyleClass().add("app-dialog-actions"); footer.setAlignment(Pos.CENTER_RIGHT); footer.setMinHeight(Region.USE_PREF_SIZE); VBox formContent=new VBox(18,fields,formError); formContent.setPadding(new Insets(18,18,0,18)); formContent.setMaxWidth(Double.MAX_VALUE); ScrollPane formScroll=new ScrollPane(formContent); formScroll.getStyleClass().add("new-request-form-scroll"); formScroll.setHbarPolicy(ScrollPane.ScrollBarPolicy.NEVER); formScroll.setVbarPolicy(ScrollPane.ScrollBarPolicy.AS_NEEDED); formScroll.setFitToWidth(true); formScroll.setPannable(false); formContent.prefWidthProperty().bind(formScroll.viewportBoundsProperty().map(b->b.getWidth())); VBox.setVgrow(formScroll,Priority.ALWAYS); VBox body=new VBox(12,formScroll,footer); body.setPadding(new Insets(0,18,18,18)); body.setMaxWidth(Double.MAX_VALUE); body.setMaxHeight(Double.MAX_VALUE); validate.run(); return body; }
    private static Button semanticButton(ControlStyles.Purpose purpose, ControlStyles.Size size, String text, javafx.event.EventHandler<javafx.event.ActionEvent> handler) { return ActionButtonFactory.semantic(text,handler,purpose,size); }
    private static void styleRequestControls(Control... controls) { for (Control control : controls) ControlStyles.formControl(control); }
    private static void updateInvalidStates(TextField title, ComboBox<?> type, ComboBox<?> method, ComboBox<?> status, DatePicker rangeStart, DatePicker rangeEnd) {
        ControlStyles.setInvalid(title,title.getText()==null||title.getText().trim().isEmpty());
        ControlStyles.setInvalid(type,type.getValue()==null); ControlStyles.setInvalid(method,method.getValue()==null); ControlStyles.setInvalid(status,status.getValue()==null);
        boolean invalidRange=rangeStart.getValue()!=null&&rangeEnd.getValue()!=null&&rangeStart.getValue().isAfter(rangeEnd.getValue());
        ControlStyles.setInvalid(rangeStart,invalidRange); ControlStyles.setInvalid(rangeEnd,invalidRange);
    }
    private String validateRequest(RequestedFromSelection requestedFrom,TextField titleField,ComboBox<MaterialTypeDto> materialType,ComboBox<RequestMethodDto> requestMethod,ComboBox<RequestStatusDto> requestStatus){ return validateRequestFields(requestedFrom,titleField.getText(),materialType.getValue(),requestMethod.getValue(),requestStatus.getValue()); }
    static String validateRequestFields(RequestedFromSelection requestedFrom,String title,MaterialTypeDto materialType,RequestMethodDto requestMethod,RequestStatusDto requestStatus){ if(!validRequestedFrom(requestedFrom))return "Requested From is required."; if(title==null||title.trim().isEmpty())return "Title is required."; if(materialType==null)return "Material Type is required."; if(requestMethod==null)return "Request Method is required."; if(requestStatus==null)return "Status is required."; return null; }
    static boolean saveEligible(int loading,boolean saving,String validationError){return loading<=0&&!saving&&validationError==null;}
    static Integer selectedUserId(CaseTaskService.AssignableUserOption user){return user==null?null:user.id();}
    static boolean validRequestedFrom(RequestedFromSelection selection){return selection!=null&&selection.entityId()!=null&&selection.entityId()>0&&selection.contact()!=selection.organization();}
    private MaterialRequestServicePort.CreateMaterialRequestCommand toCreateCommand(RequestedFromSelection rf,MaterialTypeDto materialType,String title,String description,RequestMethodDto requestMethod,RequestStatusDto requestStatus,CaseTaskService.AssignableUserOption by,CaseTaskService.AssignableUserOption assignee,String followUpInterval,LocalDate requestDate,LocalDate dueDate,LocalDate rangeStart,LocalDate rangeEnd){ return new MaterialRequestServicePort.CreateMaterialRequestCommand(tenant(),actor(),cid(),materialType.id(),title,description,rf!=null&&rf.contact()?rf.entityId().intValue():null,rf!=null&&rf.organization()?rf.entityId().intValue():null,null,requestMethod.systemKey()==null?requestMethod.name():requestMethod.systemKey(),requestStatus.systemKey()==null?requestStatus.name():requestStatus.systemKey(),selectedUserId(by),assignee==null?null:assignee.id(),at(requestDate),rangeStart,rangeEnd,dueDate,null,intervalDays(followUpInterval)); }
    private LocalDateTime defaultRequestedAt(){ return LocalDateTime.now(); }
    static String validateRequestedRange(LocalDate start,LocalDate end){return start!=null&&end!=null&&start.isAfter(end)?"Requested Date Start cannot be after Requested Date End.":null;}
    static LocalDateTime withPreservedTime(LocalDate date,LocalDateTime persisted){if(date==null)return null;return date.atTime(persisted==null?LocalTime.MIDNIGHT:persisted.toLocalTime());}
    private static void configureFollowUpInterval(ChoiceBox<String> box){box.getItems().setAll("None","Daily","Every 3 days","Weekly","Every 2 weeks","Every 30 days");box.getSelectionModel().selectFirst();box.setMaxWidth(Double.MAX_VALUE);}
    static Integer intervalDays(String value){return switch(nvl(value,"None")){case "Daily"->1;case "Every 3 days"->3;case "Weekly"->7;case "Every 2 weeks"->14;case "Every 30 days"->30;default->null;};}
    static String intervalChoice(Integer days){return days==null?"None":switch(days){case 1->"Daily";case 3->"Every 3 days";case 7->"Weekly";case 14->"Every 2 weeks";case 30->"Every 30 days";default->"None";};}
    static String calculatedFollowUpText(Integer days,LocalDateTime saved){return days==null?(saved==null?"No recurring follow-up scheduled":"One-time: "+fmt(saved)):"Calculated when saved (approximately "+fmt(LocalDateTime.now().plusDays(days))+")";}

    private void saveNewRequest(Stage stage,MaterialRequestServicePort.CreateMaterialRequestCommand cmd,AtomicBoolean dialogSaving,Runnable validate){ if(!savingRequest.compareAndSet(false,true))return; dialogSaving.set(true); validate.run(); long c=cmd.caseId(); int g=gen.get(); ex.submit(()->{try{ if(Platform.isFxApplicationThread()) throw new IllegalStateException("Material request create must run off the JavaFX application thread."); svc.createMaterialRequest(cmd); Platform.runLater(()->{savingRequest.set(false);dialogSaving.set(false); if(stage.getScene()==null||stage.getOwner()==null||stale(g,c))return; stage.close(); refresh();});}catch(Exception x){LOG.warn("Material request create failed caseId={} generation={}",c,g,x);Platform.runLater(()->{savingRequest.set(false);dialogSaving.set(false); if(stage.getScene()!=null&&!stale(g,c)){validate.run();AppDialogs.showError(stage,"Requests",friendlyMutationError(x));}});}}); }
    private static String friendlyMutationError(Throwable x){Throwable t=x;while(t.getCause()!=null)t=t.getCause(); if(t instanceof IllegalArgumentException||t instanceof IllegalStateException){String m=t.getMessage(); if(m!=null&&!m.isBlank()&&!m.toLowerCase(Locale.ROOT).contains("sql"))return m;} return "The material request could not be saved. Please review the fields and try again."; }
    RequestedFromSelection showRequestedFromChooser(Window stage){ if(caseDao==null)return null; try{RequestedFromWorkflowDialog.Selection r=RequestedFromWorkflowDialog.show(stage, () -> new RequestedFromWorkflowDialog.DirectoryData(caseDao.findSelectableContactsForTenant(), caseDao.findSelectableOrganizationsForTenant(), organizationDao==null?List.of():organizationDao.findOrganizationTypes(), caseService==null?List.of():caseService.listRequestedFromCaseParties(cid(),tenant())), ex); if(r==null)return null; Long id=r.id(); String label=r.label(); if(r.createNew()){id=createRequestedFromEntity(r); label=createdRequestedFromLabel(r,id);} return id==null?null:newRequestedFromSelection(r,id,label);}catch(Exception x){LOG.warn("Requested From chooser failed caseId={}",cid(),x);AppDialogs.showError(stage,"Requests","Requested From choices could not be loaded. Please try again.");return null;} }
    private RequestedFromSelection newRequestedFromSelection(RequestedFromWorkflowDialog.Selection r,Long id,String label){ if("contact".equalsIgnoreCase(r.entityType())){ ContactCardFactory.ContactCardModel m=r.contactModel()!=null?r.contactModel():new ContactCardFactory.ContactCardModel(id.intValue(),label,null,null,null); return new RequestedFromSelection(r.entityType(),id,label,m,null);} OrganizationCardFactory.OrganizationCardModel m=r.organizationModel()!=null?r.organizationModel():new OrganizationCardFactory.OrganizationCardModel(id.intValue(),label,r.organizationTypeId(),null,null,null,null,null,null,null,null,null,null,null,null); return new RequestedFromSelection(r.entityType(),id,label,null,m); }
    private Long createRequestedFromEntity(RequestedFromWorkflowDialog.Selection r){int tenant=tenant(); if("contact".equalsIgnoreCase(r.entityType())){if(contactDao==null)throw new IllegalStateException("Contact creation is unavailable."); return Long.valueOf(contactDao.createContact(new ContactDao.CreateContactRequest(tenant,null,null,trim(r.contactFirstName()),trim(r.contactLastName()),null,null,null,null,null,false,false)));} if(organizationDao==null)throw new IllegalStateException("Organization creation is unavailable."); return Long.valueOf(organizationDao.create(new OrganizationDao.OrganizationCreateRequest(tenant,r.organizationTypeId(),trim(r.organizationName()),null,null,null,null,null,null,null,null,null,null,null)));}
    private static String createdRequestedFromLabel(RequestedFromWorkflowDialog.Selection r,Long id){ if("contact".equalsIgnoreCase(r.entityType())){String n=nvl((trim(r.contactFirstName())+" "+trim(r.contactLastName())).trim(),null); return n==null?"Contact #"+id:n;} return nvl(trim(r.organizationName()),"Organization #"+id); }
