    private static void applyNewRequestStageSize(Stage stage,Region root){ stage.getScene().getRoot().applyCss(); stage.getScene().getRoot().layout(); Rectangle2D bounds=Screen.getScreensForRectangle(stage.getX(),stage.getY(),Math.max(stage.getWidth(),1),Math.max(stage.getHeight(),1)).stream().findFirst().orElse(Screen.getPrimary()).getVisualBounds(); double width=Math.min(Math.max(NEW_REQUEST_WIDTH,root.prefWidth(-1)),bounds.getWidth()); double height=Math.min(Math.max(NEW_REQUEST_HEIGHT,root.prefHeight(width)),bounds.getHeight()); width=Math.max(Math.min(NEW_REQUEST_MIN_WIDTH,bounds.getWidth()),width); height=Math.max(Math.min(NEW_REQUEST_MIN_HEIGHT,bounds.getHeight()),height); root.setPrefSize(width,height); root.setMinSize(Math.min(NEW_REQUEST_MIN_WIDTH,width),Math.min(NEW_REQUEST_MIN_HEIGHT,height)); stage.setMinWidth(Math.min(NEW_REQUEST_MIN_WIDTH,width)); stage.setMinHeight(Math.min(NEW_REQUEST_MIN_HEIGHT,height)); stage.setWidth(width); stage.setHeight(height); Window owner=stage.getOwner(); if(owner!=null){stage.setX(owner.getX()+(owner.getWidth()-width)/2.0);stage.setY(owner.getY()+(owner.getHeight()-height)/2.0);}else stage.centerOnScreen(); if(stage.getX()<bounds.getMinX())stage.setX(bounds.getMinX()); if(stage.getY()<bounds.getMinY())stage.setY(bounds.getMinY()); if(stage.getX()+stage.getWidth()>bounds.getMaxX())stage.setX(bounds.getMaxX()-stage.getWidth()); if(stage.getY()+stage.getHeight()>bounds.getMaxY())stage.setY(bounds.getMaxY()-stage.getHeight()); }
    private static void applyStageSize(Stage stage,Region root,double preferredWidth,double preferredHeight,double minimumWidth,double minimumHeight){ stage.getScene().getRoot().applyCss(); stage.getScene().getRoot().layout(); Rectangle2D bounds=Screen.getScreensForRectangle(stage.getX(),stage.getY(),Math.max(stage.getWidth(),1),Math.max(stage.getHeight(),1)).stream().findFirst().orElse(Screen.getPrimary()).getVisualBounds(); double width=Math.min(Math.max(preferredWidth,root.prefWidth(-1)),bounds.getWidth()); double height=Math.min(Math.max(preferredHeight,root.prefHeight(width)),bounds.getHeight()); width=Math.max(Math.min(minimumWidth,bounds.getWidth()),width); height=Math.max(Math.min(minimumHeight,bounds.getHeight()),height); root.setPrefSize(width,height); root.setMinSize(Math.min(minimumWidth,width),Math.min(minimumHeight,height)); stage.setMinWidth(Math.min(minimumWidth,width)); stage.setMinHeight(Math.min(minimumHeight,height)); stage.setWidth(width); stage.setHeight(height); Window owner=stage.getOwner(); if(owner!=null){stage.setX(owner.getX()+(owner.getWidth()-width)/2.0);stage.setY(owner.getY()+(owner.getHeight()-height)/2.0);}else stage.centerOnScreen(); if(stage.getX()<bounds.getMinX())stage.setX(bounds.getMinX()); if(stage.getY()<bounds.getMinY())stage.setY(bounds.getMinY()); if(stage.getX()+stage.getWidth()>bounds.getMaxX())stage.setX(bounds.getMaxX()-stage.getWidth()); if(stage.getY()+stage.getHeight()>bounds.getMaxY())stage.setY(bounds.getMaxY()-stage.getHeight()); }
