    VBox requestUpdatesSection(Window owner,long requestId,long caseId,int tenant,int actor,int generation,AtomicReference<MaterialRequestDetailDto> detailRef){
        Label heading=title("Updates");TextArea editor=new TextArea();editor.setPromptText("Add a note about this request…");editor.setWrapText(true);editor.setPrefRowCount(3);editor.setMaxWidth(Double.MAX_VALUE);ControlStyles.formControl(editor);Button add=semanticButton(ControlStyles.Purpose.PRIMARY, ControlStyles.Size.STANDARD, "Add Note",null);Label stateLabel=muted("Loading updates…");VBox feed=new VBox(10);AtomicBoolean submitting=new AtomicBoolean();
        Runnable validate=()->add.setDisable(submitting.get()||editor.getText()==null||editor.getText().trim().isEmpty()||editor.getText().trim().length()>4000);editor.textProperty().addListener((o,a,b)->validate.run());
        AtomicReference<Runnable> load=new AtomicReference<>();load.set(()->{stateLabel.setText("Loading updates…");stateLabel.setVisible(true);stateLabel.setManaged(true);feed.getChildren().clear();ex.submit(()->{try{List<MaterialRequestUpdateDto> rows=svc.listUpdates(caseId,requestId,tenant,actor);Platform.runLater(()->{if(stale(generation,caseId)||owner==null)return;renderRequestUpdates(feed,stateLabel,rows);});}catch(Exception failure){LOG.warn("Material request updates load failed caseId={} requestId={}",caseId,requestId,failure);Platform.runLater(()->{stateLabel.setText("Updates could not be loaded.");stateLabel.setVisible(true);stateLabel.setManaged(true);Button retry=semanticButton(ControlStyles.Purpose.SECONDARY, ControlStyles.Size.STANDARD, "Retry",e->load.get().run());feed.getChildren().setAll(retry);});}});});
        add.setOnAction(e->{String body=editor.getText()==null?"":editor.getText().trim();if(body.isEmpty()||body.length()>4000||!submitting.compareAndSet(false,true))return;validate.run();ex.submit(()->{try{svc.addNote(new MaterialRequestServicePort.AddMaterialRequestNoteCommand(tenant,actor,caseId,requestId,body));MaterialRequestDetailDto refreshed=svc.getMaterialRequest(caseId,requestId,tenant,actor).orElseThrow();Platform.runLater(()->{if(stale(generation,caseId)||owner==null)return;detailRef.set(refreshed);submitting.set(false);editor.clear();validate.run();load.get().run();refresh();});}catch(Exception failure){LOG.warn("Material request note save failed caseId={} requestId={}",caseId,requestId,failure);Platform.runLater(()->{submitting.set(false);validate.run();stateLabel.setText("Note could not be added. Your text has been kept.");stateLabel.setVisible(true);stateLabel.setManaged(true);});}});});
        HBox composerActions=new HBox(add);composerActions.setAlignment(Pos.CENTER_RIGHT);ScrollPane historyScroll=new ScrollPane(feed);historyScroll.getStyleClass().add("material-request-updates-history");historyScroll.setFitToWidth(true);historyScroll.setHbarPolicy(ScrollPane.ScrollBarPolicy.NEVER);historyScroll.setVbarPolicy(ScrollPane.ScrollBarPolicy.AS_NEEDED);historyScroll.setPannable(false);feed.setMaxWidth(Double.MAX_VALUE);feed.prefWidthProperty().bind(historyScroll.viewportBoundsProperty().map(b->b.getWidth()));VBox box=new VBox(10,heading,editor,composerActions,stateLabel,historyScroll);box.getStyleClass().add("material-request-updates");box.setPadding(new Insets(18));box.setMinWidth(0);box.setMaxWidth(Double.MAX_VALUE);VBox.setVgrow(historyScroll,Priority.ALWAYS);validate.run();load.get().run();return box;
    }
    static void renderRequestUpdates(VBox feed,Label stateLabel,List<MaterialRequestUpdateDto> rows){
        feed.getChildren().clear();
        List<MaterialRequestUpdateDto> safe=rows==null?List.of():rows;
        if(safe.isEmpty()){
            stateLabel.setText("No updates yet.");stateLabel.setVisible(true);stateLabel.setManaged(true);return;
        }
        stateLabel.setVisible(false);stateLabel.setManaged(false);
        for(MaterialRequestUpdateDto row:safe){
            String when=row.createdAt()==null?"Unknown time":row.createdAt().format(DateTimeFormatter.ofPattern("MMM d, yyyy 'at' h:mm a"));
            Label meta=new Label(nvl(row.actorDisplayName(),"Unknown user")+" · "+when);
            meta.getStyleClass().add("request-update-meta");
            Label body=new Label(nvl(row.body(),""));
            body.setWrapText(true);body.setMaxWidth(Double.MAX_VALUE);
            body.getStyleClass().add("request-update-body");
            VBox entry;
            if(isUserNote(row.updateType())){
                entry=new VBox(6,meta,body);
                entry.setPadding(new Insets(10,12,10,12));
                entry.getStyleClass().addAll("secondary-panel","request-update-note-card");
            }else{
                entry=new VBox(1,body,meta);
                entry.setPadding(new Insets(3,6,3,6));
                entry.getStyleClass().add("request-update-system-row");
            }
            entry.setMinWidth(0);entry.setMaxWidth(Double.MAX_VALUE);
            feed.getChildren().add(entry);
        }
    }
    static boolean isUserNote(String updateType){return "USER_NOTE".equals(updateType);}

    private void loadEditRequestData(long requestId,long capturedCase,int capturedTenant,int capturedActor,int capturedGeneration,Window dialogOwner,TextField titleField,TextArea description,AtomicReference<MaterialRequestDetailDto> detailRef,AtomicReference<Runnable> detailLoaded,AtomicReference<RequestedFromSelection> requestedFrom,Runnable renderRequestedFrom,ColorCodedComboBox<MaterialTypeDto> materialType,ColorCodedComboBox<RequestMethodDto> requestMethod,ColorCodedComboBox<RequestStatusDto> requestStatus,UserSelectionField<CaseTaskService.AssignableUserOption> requestedBy,UserSelectionField<CaseTaskService.AssignableUserOption> assignedTo,ChoiceBox<String> followUpInterval,DatePicker requestDate,DatePicker dueDate,DatePicker requestedRangeStart,DatePicker requestedRangeEnd,Label nextFollowUpDisplay,AtomicInteger loading,Runnable after){ materialType.setDisable(true);requestMethod.setDisable(true);requestStatus.setDisable(true);setUserSelectorsLoading(requestedBy,assignedTo,true); ex.submit(()->{try{ if(Platform.isFxApplicationThread())throw new IllegalStateException("Material request editor data must load off the JavaFX application thread."); MaterialRequestDetailDto d=svc.getMaterialRequest(capturedCase,requestId,capturedTenant,capturedActor).orElseThrow(); List<MaterialTypeDto> types=svc.listEffectiveMaterialTypes(capturedTenant); List<RequestMethodDto> methods=svc.listEffectiveRequestMethods(capturedTenant); List<RequestStatusDto> statuses=svc.listEffectiveRequestStatuses(capturedTenant); List<CaseTaskService.AssignableUserOption> users=caseTaskService==null?List.of():caseTaskService.loadAssignableUsers(capturedTenant); Platform.runLater(()->{ if(stale(capturedGeneration,capturedCase)||dialogOwner==null)return; detailRef.set(d); titleField.setText(nvl(d.title(),"")); description.setText(nvl(d.description(),"")); materialType.getItems().setAll(withLegacyType(types,d)); requestMethod.getItems().setAll(withLegacyMethod(methods,d.requestMethod())); requestStatus.getItems().setAll(withLegacyStatus(statuses,d.status())); requestedBy.setCandidates(withLegacyUser(users,d.requestedByUserId(),d.requestedByDisplayName())); assignedTo.setCandidates(withLegacyUser(users,d.assignedToUserId(),d.assignedToDisplayName())); selectById(materialType,d.materialTypeId()); selectMethod(requestMethod,d.requestMethod()); selectStatus(requestStatus,d.status()); selectUser(requestedBy,d.requestedByUserId()); selectUser(assignedTo,d.assignedToUserId()); followUpInterval.getSelectionModel().select(intervalChoice(d.followUpIntervalDays())); requestDate.setValue(toDate(d.requestedAt())); dueDate.setValue(d.expectedResponseDate()); requestedRangeStart.setValue(d.requestedRangeStartDate()); requestedRangeEnd.setValue(d.requestedRangeEndDate()); nextFollowUpDisplay.setText(calculatedFollowUpText(d.followUpIntervalDays(),d.nextFollowUpAt())); requestedFrom.set(selectionFromDetail(d)); renderRequestedFrom.run(); loading.decrementAndGet(); materialType.setDisable(false);requestMethod.setDisable(false);requestStatus.setDisable(false);setUserSelectorsLoading(requestedBy,assignedTo,false);detailLoaded.get().run(); after.run(); }); }catch(Exception x){LOG.warn("Material request editor load failed caseId={} requestId={}",capturedCase,requestId,x);Platform.runLater(()->{loading.decrementAndGet();after.run();AppDialogs.showError(dialogOwner,"Requests","Material request could not be loaded.");});}}); }
    private static List<MaterialTypeDto> withLegacyType(List<MaterialTypeDto> rows,MaterialRequestDetailDto d){if(rows.stream().anyMatch(x->x.id()==d.materialTypeId()))return rows;var out=new ArrayList<MaterialTypeDto>(rows);out.add(new MaterialTypeDto(d.materialTypeId(),d.shaleClientId(),d.materialTypeSystemKey(),nvl(d.materialTypeName(),"Saved material type"),null,null,0));return out;}
