    private static List<RequestStatusDto> withLegacyStatus(List<RequestStatusDto> rows,String v){if(v==null||rows.stream().anyMatch(x->lookupValueMatches(x.systemKey(),x.name(),v)))return rows;var out=new ArrayList<RequestStatusDto>(rows);out.add(new RequestStatusDto(0,null,v,v,0,true,false));return out;}
