    private <T>void runRead(String op,Supplier<T>w,java.util.function.Consumer<T>ok,String msg){ ex.submit(()->{try{T t=w.get();Platform.runLater(()->ok.accept(t));}catch(Exception x){LOG.warn("Case Materials read failed op={} caseId={} generation={}",op,cid(),gen.get(),x);Platform.runLater(()->showInlineError(msg));}});} private void showInlineError(String m){list.getChildren().clear(); Button r=semanticButton(ControlStyles.Purpose.SECONDARY,ControlStyles.Size.STANDARD,"Retry",e->refresh()); show(status,m); list.getChildren().add(r); AppDialogs.showError(owner.get(),"Requests",m);} private boolean stale(int g,long c){return g!=gen.get()||cid()!=c;} private long cid(){return caseId.get();} private int tenant(){return state.getShaleClientId();} private int actor(){Integer i=state.getUserId();return i==null?0:i;}
